files.tokens.css:
/*
 * Runtime customization with CSS custom properties, no Sass needed.
 * Empty by default, so the playground renders Bootstrap's defaults.
 *
 * This file goes through the same PostCSS step as Bootstrap, so write tokens
 * unprefixed like the Sass docs (`--border-radius`) or prefixed like
 * `dist/css/bootstrap.css` (`--bs-border-radius`). Both end up as `--bs-*`.
 * See https://getbootstrap.com/docs/6.0/getting-started/css-variables/
 */

/*
 * Global tokens. Bootstrap outputs them unlayered on `:root`, so these
 * overrides stay unlayered too. They win because this file loads after
 * Bootstrap.
 */
:root {
  /* --border-radius: .25rem; */
  /* --primary-base: oklch(55% .25 260); */
  /* --bg-body: #f8f9fa; */
}

/*
 * Component tokens and custom rules go in Bootstrap's `custom` layer. It comes
 * after `components`, so these override component tokens, and helpers and
 * utilities still win.
 */
@layer custom {
  /* .alert { */
  /*   --alert-padding-x: 2rem; */
  /* } */
}

files.postcss.config.js:
// Mirrors Bootstrap's own `build/postcss.config.mjs` so the CSS compiled here
// matches `dist/css/bootstrap.css`: every custom property gets the `--bs-`
// prefix (Bootstrap's JavaScript reads the prefixed names), then Autoprefixer
// runs against the targets in `.browserslistrc` (copied from Bootstrap).
import postcssPrefixCustomProperties from 'postcss-prefix-custom-properties'
import autoprefixer from 'autoprefixer'

export const DEFAULT_PREFIX = 'bs-'

// A stylesheet picks another prefix with a loud comment, which Sass keeps:
// `/*! playground-prefix: "x-" */`, or `""` for none, like the docs' npm and
// webpack guides, which run Autoprefixer only. The comment is removed.
const PREFIX_MARKER = /^!?\s*playground-prefix:\s*"([^"]*)"\s*$/

// The prefix a stylesheet asks for, or undefined.
export const readPrefix = source => source.match(/\/\*!?\s*playground-prefix:\s*"([^"]*)"\s*\*\//)?.[1]

const escapeRegExp = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

const prefixCustomProperties = {
  postcssPlugin: 'playground-prefix-custom-properties',
  Once(root) {
    let prefix = DEFAULT_PREFIX
    root.walkComments(comment => {
      const match = comment.text.match(PREFIX_MARKER)
      if (match) {
        prefix = match[1]
        comment.remove()
      }
    })

    if (prefix) {
      postcssPrefixCustomProperties({
        prefix,
        ignore: [new RegExp(`^--${escapeRegExp(prefix)}`), /^--bd-/]
      }).Once(root)
    }
  }
}

export default {
  plugins: [
    prefixCustomProperties,
    autoprefixer({ cascade: false })
  ]
}

files.vite.config.js:
import { defineConfig } from 'vite'

// Same floors as Bootstrap's `.browserslistrc`. Lower targets make the
// minifier rewrite `light-dark()`, which breaks `data-bs-theme`.
const cssTarget = ['chrome130', 'edge130', 'firefox132', 'safari18']

export default defineConfig({
  build: { target: cssTarget, cssTarget }
})
